"""Exact complete-frame crops only. Art and prop pixels are generated by GPT."""
from pathlib import Path
import hashlib
import json
from PIL import Image

ROOT = Path(__file__).resolve().parent
SOURCE_NAME = 'attempt-2.png'
PHASES = ['raised_apex', 'downswing', 'contact', 'recovery']
DURATIONS_MS = [230, 120, 230, 320]
TRANSLATION = (0, 0)

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def build():
    source = ROOT / 'sources' / SOURCE_NAME
    im = Image.open(source).convert('RGBA')
    assert im.size == (1024, 1536), f'Unreviewed source canvas: {im.size}; never automatically resize'
    frames = []
    sheet = Image.new('RGBA', (2048, 768))
    for index, phase in enumerate(PHASES):
        cell_x, cell_y = (index % 2) * 512, (index // 2) * 768
        crop = [cell_x, cell_y, cell_x + 512, cell_y + 768]
        frame = Image.new('RGBA', (512, 768))
        frame.paste(im.crop(crop), TRANSLATION)
        output = ROOT / f'registered/hoe_west_{index}.png'
        frame.save(output)
        sheet.paste(frame, (index * 512, 0))
        frames.append({'pose_id': f'hoe_west_{index}', 'phase': phase,
                       'source': 'sources/' + SOURCE_NAME, 'source_sha256': sha(source),
                       'source_rect_px': crop, 'whole_frame_translation_px': TRANSLATION,
                       'scale': 1, 'alpha_processing': 'none; source alpha preserved including known neighboring-cell fragments; rejected source not sanitized',
                       'output': str(output.relative_to(ROOT)), 'sha256': sha(output),
                       'alpha_bbox_px': frame.getchannel('A').getbbox(),
                       'duration_ms': DURATIONS_MS[index]})
    sheet.save(ROOT / 'registered/hoe-west-a-sheet.png')
    manifest = {'schema_version': 1, 'template_id': 'adult-standard-v1',
                'motion_set_id': 'hoe-west-proof-v2', 'action_id': 'hoe', 'direction': 'west',
                'status': 'rejected', 'user_accepted': False,
                'canvas_px': [512, 768], 'root_anchor_px': [256, 708],
                'root_anchor_scope': 'nominal review origin only; raw source shoe stance/root is not approved or stabilized',
                'density_check': 'failed: recovery head approximately219x218px vs239x242px reference with same outline convention; no resampling performed',
                'tool_projection_contract': 'requested strict image-plane300px shaft; measured about316..404px so contract failed; actual3D orientation not inferred',
                'display_scale': 138/582, 'reference_nominal_standing_character_display_height_px': 138,
                'cycle_duration_ms': sum(DURATIONS_MS),
                'move_policy': 'stationary full-frame proof; no gameplay execution',
                'repeat_policy': 'review replay only; entry/exit transition not approved',
                'event': {'id': 'visual_contact_only', 'frame_index': 2,
                          'time_ms': sum(DURATIONS_MS[:2]), 'gameplay_transaction': False},
                'registration_script_sha256': sha(Path(__file__)), 'frames': frames}
    (ROOT/'registered/registration.json').write_text(json.dumps(manifest, indent=2)+'\n')
    print(json.dumps({'frames': 4, 'canvas': [512,768], 'source_sha256': sha(source)}))

if __name__ == '__main__':
    build()
